const today = new Date();
today.setHours(0,0,0,0);
const CERTS = [
  { key: 'gas_safety', label: 'Gas Safety' },
  { key: 'eicr', label: 'EICR' },
  { key: 'epc', label: 'EPC' }
];

function daysUntil(dateStr) {
  const d = new Date(dateStr);
  d.setHours(0,0,0,0);
  return Math.round((d.getTime() - today.getTime()) / 86400000);
}

function applicableThreshold(daysLeft) {
  if (daysLeft > 60) return null;
  if (daysLeft <= 7) return 7;
  if (daysLeft <= 30) return 30;
  return 60;
}

const out = [];
for (const item of $input.all()) {
  const row = item.json;
  const update = { row_number: row.row_number, property_ref: row.property_ref };
  const alerts = [];

  for (const cert of CERTS) {
    const expiry = row[`${cert.key}_expiry`];
    const daysLeft = daysUntil(expiry);
    const status = daysLeft < 0 ? 'overdue' : (daysLeft <= 60 ? 'due_soon' : 'valid');
    const threshold = applicableThreshold(daysLeft);
    const lastAlertRaw = row[`${cert.key}_last_alert_days`];
    const lastAlert = (lastAlertRaw === '' || lastAlertRaw === undefined || lastAlertRaw === null) ? null : Number(lastAlertRaw);

    let newLastAlert = lastAlert;
    if (threshold !== null && (lastAlert === null || threshold < lastAlert)) {
      alerts.push({
        property_ref: row.property_ref,
        address: row.address,
        landlord_name: row.landlord_name,
        certificate: cert.label,
        expiry_date: expiry,
        days_left: daysLeft,
        threshold,
        status
      });
      newLastAlert = threshold;
    }

    update[`${cert.key}_status`] = status;
    update[`${cert.key}_last_alert_days`] = newLastAlert === null ? '' : newLastAlert;
  }

  update._alerts = alerts;
  out.push({ json: update });
}
return out;
